// Smoobu: every booking, signed with the HMAC API key (the old Api-Key header
// stops working on 31 October 2026). n8n credentials can't sign requests, so the
// key and secret come from n8n Variables: SMOOBU_API_KEY and SMOOBU_API_SECRET.
const crypto = require('crypto');

// Filters, as Smoobu query parameters. Add e.g. from / to (yyyy-mm-dd) for stays
// in a range, arrivalFrom / arrivalTo, or apartmentId for one property.
const FILTERS = { showCancellation: true, excludeBlocked: true };
const PAGE_SIZE = 100;

const key = $vars.SMOOBU_API_KEY;
const secret = $vars.SMOOBU_API_SECRET;
if (!key || !secret) throw new Error('Add the n8n Variables SMOOBU_API_KEY and SMOOBU_API_SECRET (Overview > Variables).');

const helpers = this.helpers;
const EMPTY_BODY_HASH = crypto.createHash('sha256').update('').digest('hex');
// RFC 3986: spaces as %20, and ! ' ( ) * escaped too.
const encode = (value) => encodeURIComponent(value).replace(/[!'()*]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase());
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// Canonical string, one part per line: method, path, query sorted by key,
// timestamp, nonce, SHA-256 of the body (hex), API key. Signed with the secret.
async function smoobuGet(path, query) {
  const qs = Object.entries(query)
    .filter(([, value]) => value !== undefined && value !== '')
    .map(([name, value]) => [encode(name), encode(String(value))])
    .sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0))
    .map(([name, value]) => name + '=' + value)
    .join('&');
  for (let attempt = 1; ; attempt += 1) {
    const timestamp = new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
    const nonce = crypto.randomUUID();
    const canonical = ['GET', path, qs, timestamp, nonce, EMPTY_BODY_HASH, key].join('\n');
    const signature = crypto.createHmac('sha256', secret).update(canonical).digest('base64');
    try {
      return await helpers.httpRequest({
        method: 'GET',
        url: 'https://login.smoobu.com' + path + (qs ? '?' + qs : ''),
        headers: { Accept: 'application/json', 'X-API-Key': key, 'X-Timestamp': timestamp, 'X-Nonce': nonce, 'X-Signature': signature },
        json: true,
      });
    } catch (error) {
      const status = error.httpCode ?? error.response?.status ?? error.statusCode;
      // 700 requests a minute: wait and try again, up to 3 times.
      if (String(status) === '429' && attempt < 3) { await sleep(15000); continue; }
      throw new Error('Smoobu ' + path + ' failed' + (status ? ' (HTTP ' + status + ')' : '') + ': ' + error.message);
    }
  }
}

// Pages of 100 until Smoobu's page_count is reached; one item per booking.
const out = [];
for (let page = 1; page <= 200; page += 1) {
  const body = await smoobuGet('/api/reservations', { ...FILTERS, page, pageSize: PAGE_SIZE });
  for (const booking of body.bookings || []) out.push({ json: booking });
  if (!body.page_count || page >= body.page_count) break;
  await sleep(200);
}
return out;

// Each page from Smoobu comes back as one item with a 'bookings' list.
// This turns them into one item per booking.
const out = [];
for (const page of $input.all()) {
  for (const b of (page.json.bookings || [])) out.push({ json: b });
}
return out;
